var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original only accepts strings with length > 0 or numbers
    // The patch accepts any value with length > 0, even non-strings
    // But the library throws if val is not a string or number
    // So we need to test a non-string with length > 0 that is not a number
    // For example, an array: [1,2,3] has length 3 > 0
    // Original: throws because typeof [1,2,3] is 'object', not 'string' or 'number'
    // Patched: now checks `true && val.length > 0`, so it passes the condition and calls parse
    // But parse expects a string, so it will try to call String(val) on the array
    // String([1,2,3]) is '1,2,3'
    // Then parse tries to match /^(-?(?:\d+)?\.?\d+) *(milliseconds?|msecs?|ms|...)$/i
    // '1,2,3' does not match because of the comma
    // So parse returns undefined
    // Then the library throws because parse returned undefined
    // So both builds throw
    // We need a non-string with length > 0 that when converted to string matches the regex
    // For example, a string-like object that is not a string
    // Or a number with a length property?
    // How about a string with a length property?
    // But strings already have length property
    // How about an object with a length property and a toString method that returns a number
    // Let's create a custom object
    const obj = {
      length: 3,
      toString() {
        return '123ms';
      }
    };
    // Original: typeof obj is 'object', not 'string' or 'number' → throws
    // Patched: `true && obj.length > 0` → true → calls parse(obj)
    // parse(obj) → String(obj) → '123ms' → matches → returns 123
    // So patched returns 123, original throws
    // So we can detect the difference
    assert.strictEqual(ms(obj), 123);
  });
});

